# %% ../nbs/00_claudedojo.ipynb #0c09a7a3
def _is_err(b): return b.get('type')=='tool_result' and b.get('is_error')

def _blocks(r):
    c = r.get('message', {}).get('content', '')
    return [] if isinstance(c, str) else c

def _cells(recs):
    "Kernel cell sources of the tool calls in `recs`, in order ('' for non-kernel calls)"
    return [nested_idx(b, 'input', 'code') or '' for r in recs for b in _blocks(r) if b.get('type')=='tool_use']

# %% ../nbs/00_claudedojo.ipynb #444193d2
DROP_ATT = ('hook_success', 'task_reminder')

def capture_span(
    recs, # Session records, e.g. from `load_sess`
):
    "The thread records of the captured round: bootstrap docs through the first score of the last dealt round"
    t = strip_think(sess_thread(recs))
    calls = [(k, nested_idx(b,'input','code') or '', b['id']) for k,r in enumerate(t) for b in _blocks(r) if b.get('type')=='tool_use']
    i,j = capture_slice([c for _,c,_ in calls])
    kend = first(k for k,r in enumerate(t) if any(b.get('tool_use_id')==calls[j][2] for b in _blocks(r)))
    return L(t[calls[i][0]:kend+1])

def curate_dojo(
    recs, # Session records containing a played round, e.g. from `capture_dojo`'s child
):
    "The reproducible records of the captured round: its span, minus mid-round prompts, attachments, and failed calls, deterministically re-id'd"
    t = capture_span(recs)
    bad = {b['tool_use_id'] for r in t for b in _blocks(r) if _is_err(b)}
    def _keep(r):
        if r.get('type')=='attachment' and r['attachment'].get('type') in DROP_ATT: return False
        if r.get('type')=='user' and rec_role(r)!='tool': return False
        return not any(b.get('id') in bad or b.get('tool_use_id') in bad for b in _blocks(r))
    return reid_recs(t.filter(_keep), 'claudedojo', ts='2026-01-01T00:00:00.000Z')

def dojo_cid(
    recs, # Template or captured records
):
    "The completion id recorded in the clean-round message"
    return find_cid(map(rec_txt, recs))

# %% ../nbs/00_claudedojo.ipynb #96bf7c7b
def _vis(r):
    "An assistant record's visible text, excluding thinking blocks"
    c = r.get('message', {}).get('content', '')
    return c if isinstance(c, str) else ' '.join(b.get('text','') for b in c if b.get('type')=='text')

def is_clean(
    recs, # Captured thread records
    forbid=GATE_FORBID, # Phrases that must not appear in visible assistant text
):
    "Why a captured round can't become a template: a list of problems, empty when the run is clean"
    cells = [c for r in recs for b in _blocks(r) if b.get('type')=='tool_use' and (c := nested_idx(b, 'input', 'code'))]
    outs = [rec_txt(r) for r in recs if r.get('type')=='user' and rec_role(r)=='tool']
    vis = ' '.join(_vis(r) for r in recs if r.get('type')=='assistant')
    probs = round_gates(cells, outs, vis, forbid)
    if (n := sum(1 for r in recs for b in _blocks(r) if _is_err(b))): probs.append(f'{n} failed tool calls')
    return probs

