def _load_reg(d):
    "The loaded packaged store, registered, via the shared `load_reg`"
    return load_reg(d, TMPL_DIR, 'claudedojo')

def prep_dojo(
    cwd=None, # Project to start in; the current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
):
    "Write the template session for `cwd`, register its completion id, seed its doc-state, and return the session id to resume"
    recs,meta = _load_reg(d)
    sid = save_sess(recs, cwd=cwd, ts=True)
    if ds := meta.get('doced'): _seed_doced(sid, ds)
    return sid

# %% ../nbs/00_claudedojo.ipynb #bb20faff
def append_dojo(
    sid=None, # Session id or name to append to; the project's newest transcript if None
    cwd=None, # Project directory; the current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
):
    "Append the template round to session `sid` (e.g. after a compaction), re-seed doc-state, and return `sid` to resume"
    trecs,meta = _load_reg(d)
    sid,path = resolve_session(sid, cwd or '.')
    tail = load_recs(path)
    trecs = reid_recs(trecs, f'append:{sid}:{len(tail)}')   # fresh salt per append, so repeated splices never collide
    trecs[0]['message']['content'] = APPEND_PROMPT
    append_sess(trecs, sid, cwd, ts=True)
    _seed_doced(sid, meta.get('doced') or [], merge=True)   # merge: after a compact the hook truncated the record, so this is just the round's list
    return sid

# %% ../nbs/00_claudedojo.ipynb #cff4225e
def _is_prompt(r): return r.get('type')=='user' and rec_role(r)=='user'

def _dealt(t): return any(re.match(_START_RE, nested_idx(b,'input','code') or '') for r in t for b in _blocks(r))

def strip_dojo(
    recs, # Session records, e.g. from `load_sess`
):
    "Copy of `recs` without the user turns that dealt a round (bare `dojo_start()`)"
    return _turns(recs, _is_prompt).filter(_dealt, negate=True).concat()

# %% ../nbs/00_claudedojo.ipynb #aa9b31fe
def compact_dojo(
    sid=None, # Session id or name to compact; the project's newest transcript if None
    cwd=None, # Project directory; the current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
):
    "Synthetically compact a session with the compact DSL (previous dojo rounds removed first), then append the template round; returns the session id"
    sid,_ = resolve_session(sid, cwd or '.')
    recs = load_sess(sid, cwd)
    if len(recs) > len(stripped := strip_dojo(recs)) > 0: save_sess(stripped, sid, cwd)   # a round-only session has nothing else to compact: leave it whole
    c = compact_session(sid, cwd or '.')
    return append_dojo(c.sid, cwd, d)

# %% ../nbs/00_claudedojo.ipynb #29c39ffd
@call_parse(nested=True, pos=['sess'])
def main(
    sess:str=None, # Session id or name; the project's newest transcript where omitted
    Resume:bool=False, # Append the round to an existing session after a compaction, then resume it
    Compact:bool=False, # Synthetically compact the session with the compact DSL, then append the round and resume
    sid:bool=False, # Print the prepared session id instead of launching claude
    capture:bool=False, # Play a scripted round headlessly (Agent SDK), gate it with is_clean, and store it
    current:bool=False, # Store the clean round an existing session already played (`capture_current`)
    capture_model:str='fable', # Model for --capture; the only one smart enough for clean rounds
    capture_effort:str='medium', # Adaptive thinking effort for --capture ('low'/'medium'/'high')
):
    "Prepare a session opening with the worked round and launch `claude` on it; template maintenance is `dojobuild`"
    if capture: return asyncio.run(capture_dojo(model=capture_model, effort=capture_effort))
    if current: return capture_current(sess)
    if Resume:
        try: s = append_dojo(sess)
        except FileNotFoundError as e: sys.exit(f'{e}\nNo session to append to; run claudedojo without -r to prepare a fresh one')
    elif Compact: s = compact_dojo(sess)
    else:
        if sess: sys.exit(f"unexpected argument {sess!r}: a fresh launch takes no session, and claude flag values need --flag=value form")
        s = prep_dojo()
    if sid: return print(s)
    os.execvp('claude', ['claude', *launch_config('claude'), '-r', s, *sys.argv[1:]])
